INSERT OR IGNORE INTO problems (id, difficulty, channel, sender, incoming_message, reply_text, reply_reading, reply_units) VALUES (20, 'intermediate', '#incident', 'タナカ', 'ログが `timeout` だらけ。誰か一次切り分けを', 'アラート確認しました。ボトルネックは DB 接続です。僕のハートビートは正常です。', 'あらーとかくにんしました。ぼとるねっくは DB せつぞくです。ぼくのはーとびーとはせいじょうです。', '[{"display":"アラート","reading":"あらーと"},{"display":"確認","reading":"かくにん"},{"display":"しました","reading":"しました"},{"display":"。","reading":"。"},{"display":"ボトルネック","reading":"ぼとるねっく"},{"display":"は","reading":"は"},{"display":" DB ","reading":" DB "},{"display":"接続","reading":"せつぞく"},{"display":"です","reading":"です"},{"display":"。","reading":"。"},{"display":"僕の","reading":"ぼくの"},{"display":"ハートビート","reading":"はーとびーと"},{"display":"は","reading":"は"},{"display":"正常","reading":"せいじょう"},{"display":"です","reading":"です"},{"display":"。","reading":"。"}]');
