INSERT OR IGNORE INTO problems (id, difficulty, channel, sender, incoming_message, reply_text, reply_reading, reply_units) VALUES (22, 'intermediate', '#customer-success', 'クライアントA', '仕様書の最新版、共有いただけますか？', '本日中に送ります。バージョンは `spec_v3` です。ページ数より熱量で勝負してます。', 'ほんじつちゅうにおくります。ばーじょんは `spec_v3` です。ぺーじすうよりねつりょうでしょうぶしてます。', '[{"display":"本日中に","reading":"ほんじつちゅうに"},{"display":"送ります","reading":"おくります"},{"display":"。","reading":"。"},{"display":"バージョン","reading":"ばーじょん"},{"display":"は","reading":"は"},{"display":" `","reading":" `"},{"display":"spec_v3","reading":"spec_v3"},{"display":"` ","reading":"` "},{"display":"です","reading":"です"},{"display":"。","reading":"。"},{"display":"ページ","reading":"ぺーじ"},{"display":"数より","reading":"すうより"},{"display":"熱量","reading":"ねつりょう"},{"display":"で","reading":"で"},{"display":"勝負してます","reading":"しょうぶしてます"},{"display":"。","reading":"。"}]');
