INSERT OR IGNORE INTO problems (id, difficulty, channel, sender, incoming_message, reply_text, reply_reading, reply_units) VALUES (24, 'intermediate', '#web-app', 'サトウ', 'ステージングに `feat/login` 乗せて確認お願い', 'デプロイ済みです。スモークテストから入ります。火は出してません、まだ。', 'でぷろいすみです。すもーくてすとからはいります。ひはだしてません、まだ。', '[{"display":"デプロイ","reading":"でぷろい"},{"display":"済み","reading":"すみ"},{"display":"です","reading":"です"},{"display":"。","reading":"。"},{"display":"スモークテスト","reading":"すもーくてすと"},{"display":"から","reading":"から"},{"display":"入ります","reading":"はいります"},{"display":"。","reading":"。"},{"display":"火は","reading":"ひは"},{"display":"出してません","reading":"だしてません"},{"display":"、","reading":"、"},{"display":"まだ","reading":"まだ"},{"display":"。","reading":"。"}]');
INSERT OR IGNORE INTO problems (id, difficulty, channel, sender, incoming_message, reply_text, reply_reading, reply_units) VALUES (25, 'advanced', '#incident', 'サトウ', '決済が落ちてます。顧客から怒りのメンション来てます', '> 決済が落ちてます

